INSERT INTO players (id, name, nationality, nationality_fr, position, born, image_url, image_credit, image_source) VALUES (51, 'Alexia Putellas', 'Spain', 'Espagne', 'Midfielder', 1994, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Premios_Goya_2026_-_Alexia_Putellas_%28cropped%29.jpg/500px-Premios_Goya_2026_-_Alexia_Putellas_%28cropped%29.jpg', 'Pedro J Pacheco — CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Premios_Goya_2026_-_Alexia_Putellas_(cropped).jpg');
INSERT INTO players (id, name, nationality, nationality_fr, position, born, image_url, image_credit, image_source) VALUES (52, 'Aitana Bonmatí', 'Spain', 'Espagne', 'Midfielder', 1998, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/25th_Laureus_World_Sports_Awards_-_240422_214032.jpg/500px-25th_Laureus_World_Sports_Awards_-_240422_214032.jpg', 'Barcex — CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:25th_Laureus_World_Sports_Awards_-_240422_214032.jpg');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (1, 1956, 'men', 1, 'Blackpool', 'At 41, the ''Wizard of the Dribble'' became the very first Ballon d''Or winner.', 'À 41 ans, le « sorcier du dribble » devient le tout premier Ballon d''Or de l''histoire.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (2, 1957, 'men', 2, 'Real Madrid', 'Real Madrid''s all-action forward and the driving force of their European Cup dynasty.', 'L''attaquant omniprésent du Real Madrid, moteur de sa dynastie en Coupe d''Europe.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (3, 1958, 'men', 3, 'Real Madrid', 'France''s playmaker, star of the 1958 World Cup and a European champion with Real Madrid.', 'Le meneur de jeu français, star du Mondial 1958 et champion d''Europe avec le Real Madrid.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (4, 1959, 'men', 2, 'Real Madrid', 'A second Ballon d''Or after a fourth straight European Cup with Real Madrid.', 'Deuxième Ballon d''Or après une quatrième Coupe d''Europe consécutive avec le Real Madrid.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (5, 1960, 'men', 4, 'Barcelona', 'Barcelona''s elegant playmaker, the only Spain-born winner until Rodri in 2024.', 'Le meneur élégant du Barça, seul lauréat né en Espagne jusqu''à Rodri en 2024.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (6, 1961, 'men', 5, 'Juventus', 'Argentine-born Juventus forward famous for his dribbling and rolled-down socks.', 'Attaquant de la Juventus né en Argentine, célèbre pour ses dribbles et ses chaussettes baissées.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (7, 1962, 'men', 6, 'Dukla Prague', 'Dukla Prague midfielder who led Czechoslovakia to the 1962 World Cup final.', 'Milieu du Dukla Prague qui a mené la Tchécoslovaquie en finale du Mondial 1962.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (8, 1963, 'men', 7, 'Dynamo Moscow', 'The ''Black Spider'' is still the only goalkeeper ever to win the Ballon d''Or.', 'L''« Araignée noire » reste le seul gardien de but lauréat du Ballon d''Or.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (9, 1964, 'men', 8, 'Manchester United', 'Prolific Manchester United striker and Scotland''s only winner.', 'Buteur prolifique de Manchester United et seul Écossais lauréat.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (10, 1965, 'men', 9, 'Benfica', 'Benfica''s ''Black Panther'', one of the most feared goalscorers in Europe.', 'La « Panthère noire » de Benfica, l''un des buteurs les plus redoutés d''Europe.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (11, 1966, 'men', 10, 'Manchester United', 'Midfield leader of the England side that won the 1966 World Cup.', 'Leader du milieu de l''Angleterre championne du monde en 1966.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (12, 1967, 'men', 11, 'Ferencváros', 'Ferencváros centre-forward and Hungary''s only winner.', 'Avant-centre de Ferencváros et seul Hongrois lauréat.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (13, 1968, 'men', 12, 'Manchester United', 'Manchester United''s genius winger, crowned after winning the 1968 European Cup.', 'L''ailier de génie de Manchester United, sacré après la Coupe d''Europe 1968.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (14, 1969, 'men', 13, 'AC Milan', 'AC Milan''s ''Golden Boy'' after lifting the European Cup.', 'Le « Golden Boy » de l''AC Milan, vainqueur de la Coupe d''Europe.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (15, 1970, 'men', 14, 'Bayern Munich', '''Der Bomber'', top scorer of the 1970 World Cup with 10 goals.', '« Der Bomber », meilleur buteur du Mondial 1970 avec 10 buts.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (16, 1971, 'men', 15, 'Ajax', 'Ajax''s total-football genius after winning the European Cup.', 'Le génie du football total de l''Ajax, vainqueur de la Coupe d''Europe.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (17, 1972, 'men', 16, 'Bayern Munich', '''Der Kaiser'' led West Germany to the 1972 European Championship.', '« Der Kaiser » mène la RFA au titre de champion d''Europe 1972.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (18, 1973, 'men', 15, 'Barcelona', 'Second award after a third straight European Cup with Ajax and a move to Barcelona.', 'Deuxième sacre après une troisième Coupe d''Europe d''affilée avec l''Ajax et un transfert au Barça.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (19, 1974, 'men', 15, 'Barcelona', 'First to win three, after leading the Netherlands to the 1974 World Cup final.', 'Premier triple lauréat, après avoir mené les Pays-Bas en finale du Mondial 1974.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (20, 1975, 'men', 17, 'Dynamo Kyiv', 'Dynamo Kyiv winger after winning the Cup Winners'' Cup and the UEFA Super Cup.', 'Ailier du Dynamo Kiev, vainqueur de la Coupe des coupes et de la Supercoupe de l''UEFA.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (21, 1976, 'men', 16, 'Bayern Munich', 'Second award after a third straight European Cup with Bayern Munich.', 'Deuxième sacre après une troisième Coupe d''Europe consécutive avec le Bayern Munich.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (22, 1977, 'men', 18, 'Borussia Mönchengladbach', 'Small, quick forward for Borussia Mönchengladbach and Denmark''s only winner.', 'Attaquant petit et vif du Borussia Mönchengladbach, seul Danois lauréat.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (23, 1978, 'men', 19, 'Hamburger SV', 'Hamburger SV forward, honoured in his first season after leaving Liverpool.', 'Attaquant du Hambourg SV, récompensé pour sa première saison après Liverpool.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (24, 1979, 'men', 19, 'Hamburger SV', 'Back-to-back winner after leading Hamburg to the Bundesliga title.', 'Doublé consécutif après avoir mené Hambourg au titre de Bundesliga.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (25, 1980, 'men', 20, 'Bayern Munich', 'Bayern Munich forward and Euro 1980 winner with West Germany.', 'Attaquant du Bayern Munich, champion d''Europe 1980 avec la RFA.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (26, 1981, 'men', 20, 'Bayern Munich', 'Retained the award as the Bundesliga''s top scorer.', 'Conserve son titre en finissant meilleur buteur de Bundesliga.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (27, 1982, 'men', 21, 'Juventus', 'Six goals and the Golden Boot as Italy won the 1982 World Cup.', 'Six buts et le Soulier d''or : l''Italie remporte le Mondial 1982.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (28, 1983, 'men', 22, 'Juventus', 'Juventus playmaker who finished as Serie A top scorer.', 'Meneur de jeu de la Juventus, meilleur buteur de Serie A.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (29, 1984, 'men', 22, 'Juventus', 'Nine goals as captain of France''s Euro 1984-winning side.', 'Neuf buts en capitaine de la France championne d''Europe 1984.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (30, 1985, 'men', 22, 'Juventus', 'The first player to win three Ballons d''Or in a row.', 'Premier joueur à remporter trois Ballons d''Or consécutifs.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (31, 1986, 'men', 23, 'Dynamo Kyiv', 'Dynamo Kyiv striker after winning the Cup Winners'' Cup.', 'Buteur du Dynamo Kiev après la victoire en Coupe des coupes.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (32, 1987, 'men', 24, 'AC Milan', 'Dedicated his award to Nelson Mandela in his first season at AC Milan.', 'Dédie son trophée à Nelson Mandela lors de sa première saison à l''AC Milan.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (33, 1988, 'men', 25, 'AC Milan', 'Scored the famous volley in the Euro 1988 final for the Netherlands.', 'Auteur de la célèbre volée en finale de l''Euro 1988 avec les Pays-Bas.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (34, 1989, 'men', 25, 'AC Milan', 'Retained the award after AC Milan won the European Cup.', 'Conserve son trophée après la Coupe des champions remportée par l''AC Milan.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (35, 1990, 'men', 26, 'Inter Milan', 'Captain of West Germany''s 1990 World Cup-winning team.', 'Capitaine de la RFA championne du monde en 1990.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (36, 1991, 'men', 27, 'Marseille', 'Marseille''s prolific striker, famous for his volleys, the ''papinades''.', 'Buteur prolifique de l''OM, célèbre pour ses reprises de volée, les « papinades ».');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (37, 1992, 'men', 25, 'AC Milan', 'A third Ballon d''Or, joining Cruyff and Platini.', 'Troisième Ballon d''Or, rejoignant Cruyff et Platini.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (38, 1993, 'men', 28, 'Juventus', '''Il Divin Codino'' won the UEFA Cup with Juventus.', '« Il Divin Codino » remporte la Coupe UEFA avec la Juventus.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (39, 1994, 'men', 29, 'Barcelona', 'Shared the 1994 World Cup Golden Boot and led Bulgaria to the semi-finals.', 'Co-meilleur buteur du Mondial 1994, il emmène la Bulgarie en demi-finale.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (40, 1995, 'men', 30, 'AC Milan', 'First winner after the award opened to all nationalities, and the only African winner.', 'Premier lauréat après l''ouverture à toutes les nationalités, et seul Africain sacré.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (41, 1996, 'men', 31, 'Borussia Dortmund', 'The libero at the heart of Germany''s Euro 1996 triumph.', 'Le libéro au cœur du sacre de l''Allemagne à l''Euro 1996.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (42, 1997, 'men', 32, 'Inter Milan', 'At 21, still the youngest winner ever, after a record season with Barcelona and Inter.', 'À 21 ans, toujours le plus jeune lauréat, après une saison record entre le Barça et l''Inter.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (43, 1998, 'men', 33, 'Juventus', 'Two headed goals in the World Cup final as France became world champions.', 'Deux buts de la tête en finale du Mondial : la France est championne du monde.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (44, 1999, 'men', 34, 'Barcelona', 'Barcelona''s left-footed magician and Copa América winner with Brazil.', 'Le magicien gaucher du Barça, vainqueur de la Copa América avec le Brésil.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (45, 2000, 'men', 35, 'Real Madrid', 'Won the award months after his controversial move from Barcelona to Real Madrid.', 'Sacré quelques mois après son transfert polémique du Barça au Real Madrid.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (46, 2001, 'men', 36, 'Liverpool', 'Liverpool''s lightning-quick striker after a famous treble of cups.', 'L''attaquant ultra-rapide de Liverpool, après un triplé de coupes historique.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (47, 2002, 'men', 32, 'Real Madrid', 'Eight goals and the World Cup title with Brazil after years of injuries.', 'Huit buts et le titre mondial avec le Brésil après des années de blessures.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (48, 2003, 'men', 37, 'Juventus', 'Juventus midfielder who powered his club to the Champions League final.', 'Milieu de la Juventus qui a porté son club jusqu''en finale de Ligue des champions.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (49, 2004, 'men', 38, 'AC Milan', 'Serie A top scorer with AC Milan.', 'Meilleur buteur de Serie A avec l''AC Milan.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (50, 2005, 'men', 39, 'Barcelona', 'Barcelona''s showman, once applauded by Real Madrid fans at the Bernabéu.', 'Le showman du Barça, applaudi par le public du Real au Bernabéu.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (51, 2006, 'men', 40, 'Real Madrid', 'Captain of Italy''s 2006 World Cup winners, a rare defender to win.', 'Capitaine de l''Italie championne du monde 2006, un rare défenseur sacré.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (52, 2007, 'men', 41, 'AC Milan', 'Led AC Milan to Champions League glory.', 'A mené l''AC Milan au sacre en Ligue des champions.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (53, 2008, 'men', 42, 'Manchester United', 'Champions League and Premier League double with Manchester United.', 'Doublé Ligue des champions et Premier League avec Manchester United.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (54, 2009, 'men', 43, 'Barcelona', 'First Ballon d''Or after Barcelona''s historic treble.', 'Premier Ballon d''Or après le triplé historique du Barça.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (55, 2010, 'men', 43, 'Barcelona', 'Won the first FIFA Ballon d''Or after the merger with FIFA''s award.', 'Remporte le premier FIFA Ballon d''Or, né de la fusion avec le trophée de la FIFA.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (56, 2011, 'men', 43, 'Barcelona', 'Champions League winner again with Barcelona.', 'De nouveau vainqueur de la Ligue des champions avec le Barça.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (57, 2012, 'men', 43, 'Barcelona', 'Fourth straight award after a record 91 goals in a calendar year.', 'Quatrième sacre d''affilée après un record de 91 buts sur une année civile.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (58, 2013, 'men', 42, 'Real Madrid', 'Ended Messi''s run of four straight awards.', 'Met fin à la série de quatre sacres de Messi.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (59, 2014, 'men', 42, 'Real Madrid', 'Won ''La Décima'', Real Madrid''s 10th European Cup.', 'Remporte « La Décima », la 10e Coupe d''Europe du Real Madrid.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (60, 2015, 'men', 43, 'Barcelona', 'Another treble with Barcelona alongside Suárez and Neymar.', 'Nouveau triplé avec le Barça aux côtés de Suárez et Neymar.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (61, 2016, 'men', 42, 'Real Madrid', 'Won Euro 2016 with Portugal and the Champions League with Real Madrid.', 'Champion d''Europe avec le Portugal et vainqueur de la Ligue des champions avec le Real.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (62, 2017, 'men', 42, 'Real Madrid', 'Back-to-back Champions Leagues and a fifth award, level with Messi.', 'Deuxième Ligue des champions d''affilée et cinquième sacre, à égalité avec Messi.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (63, 2018, 'men', 44, 'Real Madrid', 'World Cup finalist with Croatia, breaking the Messi-Ronaldo decade.', 'Finaliste du Mondial avec la Croatie, il brise la décennie Messi-Ronaldo.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (64, 2019, 'men', 43, 'Barcelona', 'A sixth award, a record at the time.', 'Sixième sacre, un record à l''époque.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (65, 2021, 'men', 43, 'Paris Saint-Germain', 'Copa América winner, his first major title with Argentina.', 'Vainqueur de la Copa América, son premier grand titre avec l''Argentine.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (66, 2022, 'men', 45, 'Real Madrid', 'Led Real Madrid to the Champions League and La Liga double.', 'A mené le Real Madrid au doublé Ligue des champions – Liga.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (67, 2023, 'men', 43, 'Inter Miami', 'An eighth award after winning the 2022 World Cup with Argentina.', 'Huitième sacre après le Mondial 2022 remporté avec l''Argentine.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (68, 2024, 'men', 46, 'Manchester City', 'Euro 2024 winner and the heartbeat of Manchester City''s midfield.', 'Champion d''Europe 2024 et métronome du milieu de Manchester City.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (69, 2025, 'men', 47, 'Paris Saint-Germain', 'Led PSG to its first Champions League title.', 'A mené le PSG à sa première Ligue des champions.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (70, 2026, 'men', 48, 'Bayern Munich', 'Ended England''s 25-year wait for a winner after a record-breaking season with Bayern.', 'Met fin à 25 ans d''attente pour l''Angleterre après une saison record avec le Bayern.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (71, 2018, 'women', 49, 'Lyon', 'Lyon striker and the first-ever winner of the Ballon d''Or Féminin.', 'Attaquante de Lyon et toute première lauréate du Ballon d''Or féminin.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (72, 2019, 'women', 50, 'Reign FC', 'World Cup winner, Golden Ball and Golden Boot with the United States.', 'Championne du monde, Ballon d''or et Soulier d''or du Mondial avec les États-Unis.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (73, 2021, 'women', 51, 'Barcelona', 'Led Barcelona to their first Women''s Champions League title.', 'A mené le Barça à sa première Ligue des champions féminine.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (74, 2022, 'women', 51, 'Barcelona', 'Retained the award despite a knee injury that kept her out of Euro 2022.', 'Conserve son trophée malgré une blessure au genou qui la prive de l''Euro 2022.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (75, 2023, 'women', 52, 'Barcelona', 'World Cup winner with Spain and Champions League winner with Barcelona.', 'Championne du monde avec l''Espagne et de la Ligue des champions avec le Barça.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (76, 2024, 'women', 52, 'Barcelona', 'A second straight award after another Champions League with Barcelona.', 'Deuxième sacre consécutif après une nouvelle Ligue des champions avec le Barça.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (77, 2025, 'women', 52, 'Barcelona', 'The first player to win three Ballons d''Or Féminin in a row.', 'Première joueuse à remporter trois Ballons d''Or féminins d''affilée.');
INSERT INTO awards (id, year, category, player_id, club, description_en, description_fr) VALUES (78, 2026, 'women', 51, 'Barcelona', 'A third award after a quadruple in her final Barcelona season, before joining London City Lionesses.', 'Troisième sacre après un quadruplé lors de sa dernière saison au Barça, avant de rejoindre London City Lionesses.');
